(()=>{'use strict';const E='https://sweet-art-bed8child-advocacy-page-views.jerryzuhow77.workers.dev/weekly',A=[['case-xuanxuan-shared','cases/xuanxuan/',['小璇案','小璇案','Xuan Xuan case','小璇さんの事案']],['historical-fujian-qiqi-shared','historical-cases/regions/mainland-china/fujian-qiqi/',['福建琪琪案','福建琪琪案','Fujian Qiqi case','福建・琪琪さんの事案']],['historical-tian-tian-shared','historical-cases/regions/mainland-china/tian-tian/',['甜甜案','甜甜案','Tian Tian case','甜甜さんの事案']],['historical-wanghao-shared','historical-cases/regions/taiwan/wanghao/',['王昊案','王昊案','Wang Hao case','王昊さんの事案']],['historical-fu-junxiang-shared','historical-cases/regions/taiwan/fu-junxiang/',['傅君翔案','傅君翔案','Fu Junxiang case','傅君翔さんの事案']]];const C=[['本週最多閱讀','依本週精選案件專題的實際閱讀次數排序。','次閱讀','本週排行資料正在累積中。','每週重新累積'],['本周最多阅读','依本周精选案件专题的实际阅读次数排序。','次阅读','本周排行数据正在累积中。','每周重新累积'],['Most read this week','Ranked by real weekly reads across selected case features.','reads','This week’s ranking is still collecting reads.','Resets weekly'],['今週よく読まれている記事','選定した事件特集の今週の実際の閲覧数による順位です。','回閲覧','今週のランキングを集計しています。','毎週リセット']];const L=()=>{let l=(document.documentElement.lang||'').toLowerCase();return l.startsWith('zh-hans')?1:l.startsWith('en')?2:l.startsWith('ja')?3:0};const start=async h=>{let l=L(),c=C[l],p=l===2?'../en/':l===3?'../ja/':'./';h.className='home-section weekly-reading';h.innerHTML='<div class="section-heading"><div><span class="weekly-kicker">'+c[4]+'</span><h2 id="weekly-reading-title">'+c[0]+'</h2><p>'+c[1]+'</p></div></div><ol class="weekly-list" aria-labelledby="weekly-reading-title"></ol>';let list=h.querySelector('ol');try{let r=await fetch(E+'?keys='+encodeURIComponent(A.map(x=>x[0]).join(','))+'&ts='+Date.now(),{cache:'no-store'});if(!r.ok)throw 0;let d=await r.json(),m=new Map((d.items||[]).map(x=>[x.key,+x.count||0])),v=A.map(x=>({...({key:x[0],path:x[1],title:x[2]}),count:m.get(x[0])||0})).filter(x=>x.count).sort((a,b)=>b.count-a.count);if(!v.length)throw 0;for(let[x,i]of v.map((x,i)=>[x,i])){let q=document.createElement('li'),a=document.createElement('a');a.href=p+x.path;a.innerHTML='<b>'+String(i+1)+'</b><span><strong>'+x.title[l]+'</strong><em>'+new Intl.NumberFormat().format(x.count)+' '+c[2]+'</em></span>';q.append(a);list.append(q)}}catch(_){list.outerHTML='<p class="weekly-empty">'+c[3]+'</p>'}};let s=()=>document.querySelectorAll('[data-weekly-reading]').forEach(start);document.readyState==='loading'?document.addEventListener('DOMContentLoaded',s,{once:true}):s()})();